import { useEffect, useState } from "react";

// Wrapped in <Suspense>, yet the fallback never shows
export function ProductDetails({ id }: { id: string }) {
  const [product, setProduct] = useState<Product | null>(null);
  useEffect(() => {
    fetchProduct(id).then(setProduct); // starts after render
  }, [id]);
  return <h2>{product?.name ?? "No product"}</h2>;
}

