import { Suspense, use } from "react";

function ProductDetails({ id }: { id: string }) {
  // A new Promise on every render, so every retry suspends again
  const product = use(fetchProduct(id));
  return <h2>{product.name}</h2>;
}

export function ProductPage({ id }: { id: string }) {
  return (
    <Suspense fallback={<p>Loading…</p>}>
      <ProductDetails id={id} />
    </Suspense>
  );
}

import { Suspense, use } from "react";

// Same id, same Promise: the retry finds it already settled
const cache = new Map<string, Promise<Product>>();
function getProduct(id: string) {
  let promise = cache.get(id);
  if (!promise) {
    promise = fetchProduct(id);
    cache.set(id, promise);
  }
  return promise;
}

function ProductDetails({ id }: { id: string }) {
  const product = use(getProduct(id));
  return <h2>{product.name}</h2>;
}

export function ProductPage({ id }: { id: string }) {
  return (
    <Suspense fallback={<p>Loading…</p>}>
      <ProductDetails id={id} />
    </Suspense>
  );
}
